import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"ListItem","description":"","frontmatter":{},"headers":[],"relativePath":"components/list-item.md","filePath":"components/list-item.md"}'),i={name:"components/list-item.md"};function r(s,e,n,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="listitem" tabindex="-1">ListItem <a class="header-anchor" href="#listitem" aria-label="Permalink to &quot;ListItem&quot;">​</a></h1><p>ListItem is one entry of a list: its columns hold a mark, a name and the things at its end.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for each item of a <a href="./list">List</a>; a line of a table is a row of a <a href="./table">Table</a>. An item that opens something takes <code>onclick</code> (Enter and Space press it too, except in a field inside it) or <code>href</code>; one that is only read takes <code>plain</code>, and then a <code>rule</code> under it, or a surface, so that its edge can be seen. <code>sel</code> marks the selected item; set <code>aria-selected</code> or <code>aria-current</code> on it as the list requires. When the item ends with an icon button, <code>tail</code> lines the icon up with the edge of the text.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>columns</code></td><td>required</td><td>The columns (<code>grid-template-columns</code>)</td></tr><tr><td><code>onclick</code></td><td></td><td>Makes the item pressable</td></tr><tr><td><code>href</code></td><td></td><td>Renders a link</td></tr><tr><td><code>plain</code></td><td><code>false</code></td><td>Not pressed: no hover surface</td></tr><tr><td><code>sel</code></td><td><code>false</code></td><td>Selected</td></tr><tr><td><code>rule</code></td><td><code>false</code></td><td>A line under the item, except the last</td></tr><tr><td><code>tail</code></td><td><code>false</code></td><td>pad-sm at the right, for an icon button</td></tr><tr><td><code>onkeydown</code></td><td></td><td>Called on a key; preventing it keeps the key</td></tr><tr><td><code>children</code></td><td>required</td><td>The content of the columns</td></tr></tbody></table><p>Other attributes (<code>aria-*</code>, <code>data-*</code>) go to the element.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The height comes from the content. The least height is <code>--kata-height-list-item</code>, the ink of the text and md above and below, or the height the list declares with <code>rows</code>. Every visible thing in it, a mark, a thumbnail, a control with a line or a surface and stacked content, keeps md above and below, and the item grows to fit; an icon or a markbox does not push. The columns are gap-sm apart; pad-md at the sides, or the inset the container declares. Bare text is trimmed to its ink and ends with an ellipsis. Controls inside are small buttons. Hover shows the raise surface; selected is the raise surface and a blue line of two at the left; the focus ring is drawn inside.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/list-item/" title="ListItem" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/list-item/" target="_blank" rel="noopener">ListItem</a></figcaption></figure>',11)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
